+import { transformStyleAttributes } from '../transformStyleAttributes';
+
+describe('transformStyleAttributes', () => {
+    it('replaces viewport heights throughout the tree while preserving other inline styles', () => {
+        const root = document.createElement('div');
+        root.setAttribute('style', 'height: 100vh; color: red');
+        root.innerHTML = `
+            <section style="height: 50vh !important; width: 20px">
+                <div style="height: calc(100vh - 10px); min-height: 30vh"></div>
+            </section>
+            <div style="height: 50px; width: 10vh"></div>
+            <div style="min-height: 20vh"></div>
+        `;
+
+        transformStyleAttributes(root);
+
+        expect((root as HTMLElement).style.height).toBe('auto');
+        expect((root as HTMLElement).style.color).toBe('red');
+        const elements = root.querySelectorAll<HTMLElement>('section, div');
+        expect(elements[0].style.height).toBe('auto');
+        expect(elements[0].style.getPropertyPriority('height')).toBe('important');
+        expect(elements[0].style.width).toBe('20px');
+        expect(elements[1].style.height).toBe('auto');
+        expect(elements[1].style.minHeight).toBe('30vh');
+        expect(elements[2].style.height).toBe('50px');
+        expect(elements[2].style.width).toBe('10vh');
+        expect(elements[3].style.height).toBe('');
+        expect(elements[3].style.minHeight).toBe('20vh');
+    });
+});
